e4_email_keyed_user_store.s:
Rewrite e4/src/lib/server/user.ts so e4 users live in the SAME Qdrant collection 'i' as beee users: unprefixed point ids (beee uses the raw id, e4 currently prefixes 'u_'), email as the canonical key (beee field 'e', e4 legacy field 'm'), and picture written to 'pic' so it never clobbers beee's bcrypt hash in field 'p'. This makes find-or-create by email return the SAME id both apps use for the same human.

Why: today e4 keys Google users by Google sub at point 'u_<sub>' with payload {s:'u', n, p:<picture-url>, m:<email>, d}, while beee keys by email at point <uuid> with payload {s:'u', e, p?:<bcrypt-hash>, n?, pic?, ph?, c?, d}. Same Google account therefore creates two records and the field 'p' means picture on e4 records but password on beee records; if e4 ever overwrote 'p' it would destroy beee passwords. The email-keyed, unprefixed store below resolves it.

STEP 1 — REPLACE the whole file /home/ed/i/e4/src/lib/server/user.ts. Current content is the QdrantClient + Sqids + 'u_' prefix + save_user(event,id,name,picture,email)/get_user(event,id) implementation (58 lines). New content verbatim:
  import { QdrantClient } from '@qdrant/js-client-rest';
  import { QDRANT_KEY, QDRANT_URL } from '$env/static/private';
  import type { User } from '$lib/types/user';
  (blank)
  const C = 'i';
  const local = new Map<string, User>();
  let q: QdrantClient | null = null;
  (blank)
  function client(): QdrantClient {
  	if (!q) q = new QdrantClient({ url: QDRANT_URL, apiKey: QDRANT_KEY, checkCompatibility: false });
  	return q;
  }
  (blank)
  async function find_by(field: 'e' | 'm', value: string): Promise<{ i: string; pl: Record<string, unknown> } | null> {
  	try {
  		const r = await client().scroll(C, {
  			filter: { must: [{ key: 's', match: { value: 'u' } }, { key: field, match: { value } }] },
  			limit: 1,
  			with_payload: true,
  			with_vector: false
  		});
  		const p = r.points?.[0];
  		if (!p) return null;
  		const pl = p.payload as Record<string, unknown>;
  		if (pl.s !== 'u') return null;
  		return { i: p.id as string, pl };
  	} catch {
  		return null;
  	}
  }
  (blank)
  export async function find_or_create_user(name: string, picture: string | undefined, email: string): Promise<string> {
  	const by_e = await find_by('e', email);
  	if (by_e) return by_e.i;
  	const by_m = await find_by('m', email);
  	if (by_m) {
  		try {
  			await client().setPayload(C, { points: [by_m.i], payload: { e: email }, wait: true });
  		} catch {}
  		return by_m.i;
  	}
  	const id = crypto.randomUUID();
  	const u: Record<string, unknown> = { s: 'u', e: email, n: name, m: email, d: Date.now() };
  	if (picture) u.pic = picture;
  	try {
  		await client().upsert(C, { points: [{ id, payload: u }] });
  	} catch {
  		local.set(id, u as unknown as User);
  	}
  	return id;
  }
  (blank)
  export async function get_user(id: string): Promise<User | null> {
  	try {
  		const r = await client().retrieve(C, { ids: [id] });
  		const pl = r[0]?.payload as Record<string, unknown> | undefined;
  		if (pl?.s !== 'u') return null;
  		const raw_c = pl.c;
  		return {
  			s: 'u',
  			n: (pl.n as string) || '',
  			p: (pl.pic as string) || (pl.p as string),
  			m: (pl.m as string) || (pl.e as string),
  			c: typeof raw_c === 'string' ? (raw_c as string) : undefined,
  			r: pl.r as string[] | undefined,
  			d: (pl.d as number) || 0
  		};
  	} catch {
  		return local.get(id) || null;
  	}
  }
  (blank)
  export async function find_login_user(email: string): Promise<{ i: string; n?: string; pic?: string; hash?: string } | null> {
  	const by_e = await find_by('e', email);
  	const hit = by_e || (await find_by('m', email));
  	if (!hit) return null;
  	const raw_p = hit.pl.p;
  	const hash = typeof raw_p === 'string' && raw_p.startsWith('$2') ? (raw_p as string) : undefined;
  	return {
  		i: hit.i,
  		n: (hit.pl.n as string) || undefined,
  		pic: (hit.pl.pic as string) || (hit.pl.p as string) || undefined,
  		hash
  	};
  }

NOTES: never write 'p', 'c', 'r', 'ph' — only read them — so beee data (password hash in p, classification array in c, phones in ph) is never clobbered. Referral-code generation (Sqids) is dropped: e4's UI never uses user.c (the login page's affiliate field is commented out). get_user now returns picture from pic OR p, email from e OR m, and c only when it is a string (beee stores c as an array).

STEP 2 — update the two get_user call sites that passed an event/platform arg, since the new signature is get_user(id):
(a) /home/ed/i/e4/src/routes/+layout.server.ts line 20. Current:
  const u = await get_user({ platform }, s.user.id);
Replace with:
  const u = await get_user(s.user.id);
(b) /home/ed/i/e4/src/routes/api/me/+server.ts line 7. Current:
  const u = await get_user(event, event.locals.user.id);
Replace with:
  const u = await get_user(event.locals.user.id);

STEP 3 — TESTS (write first, watch fail, then implement). Create /home/ed/i/e4/src/lib/server/user.test.ts with vi.mock of the Qdrant REST client and $env/static/private, an in-memory store that implements scroll/retrieve/upsert/setPayload exactly like beee's test fake (filter must == on every key, store keyed by id), then assert:
